AFAnalysisRule.ConfigString:
AnalysisStart := // Failsafe for backfills
If '*' < '2024-11-01 00:01:30' Then
  Exit()
Else
  True;
ElectricalConsumption := '{da6928b0-10f9-551f-2b72-71fc565a8436};Electrical energy consumption';
DeltaE := ElectricalConsumption - PrevVal(ElectricalConsumption, '*');
//DeltaValue(ElectricalConsumption)
DeltaT := '*' - PrevEvent(ElectricalConsumption, '*');
//SecSinceChange(ElectricalConsumption)
ElectricalPower := Convert(DeltaE, "MWh") / (DeltaT /3600);
ElectricalPowerReconciled := (ElectricalPower*'{98db5602-8672-59c4-03ec-f9bafa312f34};Electrical energy consumption rate (reconciled)|{0534fcf1-56c6-549f-1b2e-135f37822141};Rate')+('{98db5602-8672-59c4-03ec-f9bafa312f34};Electrical energy consumption rate (reconciled)|{d6f46c1d-3e57-533e-1b4b-9225d3cd03b5};Offset'/24);
Result := If ElectricalPower >0 Then
  ElectricalPowerReconciled
Else
  NoOutput();
Variable1 := if Result > 200 Then 0 Else Result;

Variable1 := '{1153b826-be4a-5163-3198-09293319fc80};Starch flow from storage tank'*('{f45cba72-b77b-5333-2328-78b0417b9583};Storage tank solids consistency'/100)* 1.15;
Variable2 := 15000*(22.999/100)* 1.15;
Variable3 := If BadVal('{f45cba72-b77b-5333-2328-78b0417b9583};Storage tank solids consistency') then 0 else ('{1153b826-be4a-5163-3198-09293319fc80};Starch flow from storage tank'*('{f45cba72-b77b-5333-2328-78b0417b9583};Storage tank solids consistency'/100)*1.15);
Variable4 := If BadVal('{1153b826-be4a-5163-3198-09293319fc80};Starch flow from storage tank') then 0 else ('{1153b826-be4a-5163-3198-09293319fc80};Starch flow from storage tank'*('{f45cba72-b77b-5333-2328-78b0417b9583};Storage tank solids consistency'/100)*1.15);

newbreaktag := if '{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal'>0 And PrevVal('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*') =0 and Float('*'-PrevEvent('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*'))>60 Then "false" Else PrevVal('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*');
Break := If newbreaktag = 0 or newbreaktag = "False" then "false" else "True";
JumboInt := Right('{ea18e0d6-f904-56ad-33fb-7be3b5eca5aa};Jumbo ID',6);

Variable1 := IF
(
  TagVal('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*') = 0
  AND
  TagMax('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*-1m','*') = 0
)
THEN
  0
ELSE
  1;
Variable2 := Right('{ea18e0d6-f904-56ad-33fb-7be3b5eca5aa};Jumbo ID',6);
Variable3 := If Variable1 = 1 Then 0 Else Variable2;

Variable1 := If '{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal'=0 then 0 Else TimeEq('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*-1d','*',TagVal('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*'));
L2 := TimeEq('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*','*-1m',0);
L3 := If L2 <60 and '{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal' = 0 then Prevval('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*') Else TagVal('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*');
T1 := TimeEq('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*','*-1m',TagVal('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*'));
T2 := TimeEq('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*','*-1m',PrevVal('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*'));
T3 := If '{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal'=0 then TimeEq('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*','*-1m',TagVal('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*')) - TimeEq('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*','*-1m',PrevVal('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*')) else '{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal';

T1 := TimeEq('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*','*-1m',0);
T2 := TimeEq('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*','*-1m',PrevVal('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*'));
T3 := If '{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal' <> 0 then TagVal('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*') Else (IF '{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal' = 0 AND T2 = 60 then PrevVal('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*') Else IF '{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal' = 0 AND T2 <> 60 then PrevVal('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*') Else 0);
T4 := IF Prevval('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*') = 0 AND tagval('{a43de2c2-6100-42bf-b549-77855f01b812};Time_SJ','*') < 60 then Tagval('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*') Else IF Prevval('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*') = 0 AND T2 <> 60 then TagVal('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*') ELSE IF '{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal' <> 0 then TagVal('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*') Else 0;

Variable1 := (
  TagVal('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*') <> 0
)
OR
(
  TagVal('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*') = 0
  AND
  TagMax('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*','*+1m') <> 0
);
Variable3 := Right('{ea18e0d6-f904-56ad-33fb-7be3b5eca5aa};Jumbo ID',6);
Variable4 := If Variable1 = True Then 0 Else Variable3;

Variable1 := (
  TagVal('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*') <> 0
)
OR
(
  TagVal('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*') = 0
  AND
  TagMax('{790e8b77-3446-5bfe-2dfd-ee2658df8d58};Break Signal','*','*+1m') <> 0
);
Variable2 := IF Variable1 THEN 0 ELSE Right('{ea18e0d6-f904-56ad-33fb-7be3b5eca5aa};Jumbo ID',6);
